    content: "CAT is not an exam of solving every question; it is a test of intelligent question selection and strict emotional detachment from difficult problems.\n\n## Percentile jumps come from selection skill\nBetween 90 and 99.5, content knowledge converges. Decision quality under time pressure is what separates calls.\n\n### 1. DILR: The Art of Set Filtering (First 5 Minutes)\nNever start solving the first set you see. Spend the first 4 to 5 minutes reading all sets:\n- Categorize each set as Green (familiar arrangement or matrix), Yellow (doable with table calculation), or Red (abstract games or puzzles).\n- Cracking just 2.5 to 3 sets completely often guarantees a high DILR percentile.\n\n### 2. QA: The 3-Round Solving Technique\nDivide your QA section into three distinct sweeps:\n- Round 1: Solve only direct arithmetic and simple algebra questions taking under 60 seconds.\n- Round 2: Tackle moderate questions that require about 2 minutes of calculation.\n- Round 3: Clean up remaining solvable questions. Never get trapped in a long geometry proof.\n\n### 3. Mock Test Benchmark Analysis\nTake at least 30 full-length proctored mocks. Review each question as Solved Correctly, Attempted but Wrong, or Missed Easy.\n\n## Compare CAT programmes with evidence\nUse [best CAT coaching](/best-cat-coaching) to compare test-series strength and batch mentoring quality.\n",
